package e.e.a;
import android.content.*;import android.net.Uri;import android.os.*;import android.provider.DocumentsContract;import java.io.*;import java.util.*;import org.json.*;
final class DownloadJobs115 {
 static final ArrayList<Job> jobs=new ArrayList<>();static Context app;static boolean loaded;static final Handler MAIN=new Handler(Looper.getMainLooper());static long revision;
 static final class Job{String token=UUID.randomUUID().toString(),id,tree;volatile String title,quality="",phase="キュー待ち",uri="",error="";int height,assets,finishedAssets;volatile long bytes,total=-1,assetBytes,assetSize=-1,started;volatile boolean cancelled,paused;long savedAt;JSONObject json()throws Exception{return new JSONObject().put("token",token).put("id",id).put("title",title).put("tree",tree).put("quality",quality).put("height",height).put("phase",phase).put("uri",uri).put("error",error).put("bytes",bytes).put("savedAt",savedAt);}int percent(){if("保存済み".equals(phase))return 100;if(total>0)return (int)Math.min(99,bytes*100d/total);if(assets>0)return (int)Math.min(99,(finishedAssets+(assetSize>0?Math.min(1,assetBytes/(double)assetSize):0))*100/assets);return -1;}}
 static synchronized void init(Context c){app=c.getApplicationContext();if(loaded)return;loaded=true;File store=new File(app.getFilesDir(),"mp4-downloads115.json");try{if(!store.isFile())return;String text=new String(java.nio.file.Files.readAllBytes(store.toPath()),"UTF-8");JSONArray data=new JSONArray(text);for(int i=0;i<data.length();i++){JSONObject o=data.getJSONObject(i);Job j=new Job();j.token=o.getString("token");j.id=o.getString("id");j.title=o.optString("title",j.id);j.tree=o.getString("tree");j.height=o.optInt("height");j.quality=o.optString("quality");j.phase=o.optString("phase");j.uri=o.optString("uri");j.error=o.optString("error");j.bytes=o.optLong("bytes");j.savedAt=o.optLong("savedAt");if(!Arrays.asList("保存済み","エラー","キャンセル").contains(j.phase)){j.phase="一時停止";j.paused=true;j.error="アプリ終了により中断しました。再開時は取得をやり直します。";}jobs.add(j);}}catch(Exception e){android.util.Log.w("nicoid-download","Cannot read download history",e);}}
 static synchronized Job find(String token){for(Job j:jobs)if(j.token.equals(token))return j;return null;}
 static synchronized List<Job> all(){return new ArrayList<>(jobs);}
 static synchronized void changed(Context c){revision++;save();}
 static synchronized void save(){if(app==null)return;File temp=new File(app.getFilesDir(),"mp4-downloads115.json.tmp"),dest=new File(app.getFilesDir(),"mp4-downloads115.json");try{JSONArray data=new JSONArray();for(Job j:jobs)data.put(j.json());try(FileOutputStream out=new FileOutputStream(temp)){out.write(data.toString().getBytes("UTF-8"));out.getFD().sync();}if(!temp.renameTo(dest))throw new IOException("Cannot finalize history");}catch(Exception e){android.util.Log.w("nicoid-download","Cannot save download history",e);}}
 static Intent intent(Context c,Job j){return new Intent().setClassName(c,"com.sauzask.nicoid.NicoidDownloadCache").putExtra("nicoid_mp4_job115",j.token).putExtra("id",j.id).putExtra("title",j.title);}
 static synchronized Job enqueue(Context c,String id,String title,int height){init(c);String tree=android.preference.PreferenceManager.getDefaultSharedPreferences(c).getString("mp4_tree_uri","");for(Job j:jobs)if(j.id.equals(id)&&j.height==height&&!Arrays.asList("保存済み","エラー","キャンセル").contains(j.phase))return j;Job j=new Job();j.id=id;j.title=title;j.height=height;j.tree=tree;jobs.add(j);save();return j;}
 static void submit(Context c,Job j){j.paused=j.cancelled=false;j.error="";j.bytes=0;j.total=-1;j.assets=j.finishedAssets=0;j.phase="キュー待ち";changed(c);try{Intent i=intent(c,j);if(Build.VERSION.SDK_INT>=26)c.startForegroundService(i);else c.startService(i);}catch(Exception e){j.phase="エラー";j.error="ダウンロードを開始できませんでした";changed(c);}}
 static void control(Job j,boolean pause){if("保存済み".equals(j.phase))return;j.paused=pause;j.cancelled=!pause;DownloadWorker115.cancel(j);if(!DownloadWorker115.running(j)){j.phase=pause?"一時停止":"キャンセル";DownloadWorker115.unqueue(j);changed(app);}}
 static String format(long bytes){return String.format(Locale.getDefault(),bytes>=1073741824?"%.2f GB":"%.1f MB",bytes/(bytes>=1073741824?1073741824d:1048576d));}
 static Uri document(Uri tree){return DocumentsContract.buildDocumentUriUsingTree(tree,DocumentsContract.getTreeDocumentId(tree));}
 static void export(Context c,Job j,File file)throws Exception{j.phase="保存中";Uri tree=Uri.parse(j.tree),created=null;boolean complete=false;try{created=DocumentsContract.createDocument(c.getContentResolver(),document(tree),"video/mp4",Mp4Playlist115.filename(j.title,j.id)+".part");if(created==null)throw new IOException("保存先にファイルを作成できません");try(InputStream in=new FileInputStream(file);OutputStream out=c.getContentResolver().openOutputStream(created,"wt")){if(out==null)throw new IOException("保存先を開けません");byte[] buffer=new byte[65536];int n;while((n=in.read(buffer))!=-1){if(j.cancelled||j.paused||Thread.currentThread().isInterrupted())throw new InterruptedIOException();out.write(buffer,0,n);}}if(j.cancelled||j.paused)throw new InterruptedIOException();Uri renamed=DocumentsContract.renameDocument(c.getContentResolver(),created,Mp4Playlist115.filename(j.title,j.id));if(renamed==null)throw new IOException("保存を確定できません");created=renamed;j.uri=created.toString();j.bytes=file.length();j.savedAt=System.currentTimeMillis();j.phase="保存済み";complete=true;}finally{if(!complete&&created!=null)try{DocumentsContract.deleteDocument(c.getContentResolver(),created);}catch(Exception e){android.util.Log.w("nicoid-download","Could not remove partial document",e);}}}
}
